import time

response_cache = {}
embedding_cache = {}
TTL_SECONDS = 60

def is_personalized(query):
    # not all responses are safe to cache
    return "my account" in query.lower()

def get_embedding(text):
    if text in embedding_cache:
        return "embedding hit", embedding_cache[text]
    vector = [hash(text) % 100]
    embedding_cache[text] = vector
    return "embedding miss", vector

def full_pipeline(query, context_version):
    # caching the end-to-end result, not just one stage
    embed_status, _ = get_embedding(query)
    return f"Answer for '{query}' using context v{context_version} ({embed_status})"

def get_response(query, context_version):
    if is_personalized(query):
        return full_pipeline(query, context_version) + " [not cached, personalized]"

    # the response cache key must include the retrieved context
    cache_key = (query.strip().lower(), context_version)
    cached = response_cache.get(cache_key)
    if cached and time.time() - cached["timestamp"] < TTL_SECONDS:
        return cached["value"] + " [response cache hit]"

    result = full_pipeline(query, context_version)
    response_cache[cache_key] = {"value": result, "timestamp": time.time()}
    return result + " [response cache miss]"

print(get_response("What does the Falcon plan cost?", 1))
print(get_response("What does the Falcon plan cost?", 1))
print(get_response("What is on my account?", 1))
